#' Estimate Phenological Peak Timing (Mode)
#'
#' Identifies the calendar Day of Year of maximum probability density across
#' simulated posterior curves. Curves are first rotated onto the continuous
#' Day of Biological Year (DOBY) timeline anchored at the biological minimum
#' (`D_min`) so that winter peaks straddling December 31 and January 1 are
#' summarized without circular boundary distortion before transforming back to
#' calendar `DOY`.
#'
#' @param sim_mat A numeric matrix (`n_grid x n_sims`, typically `365 x 1000`) of normalized posterior probability density curves generated by [simulate_posterior_density()].
#' @param ref_sim_mat Optional reference posterior density matrix (`n_grid x n_sims`) used to anchor `D_min` consistently across gradients. Defaults to `NULL` (computes `D_min` from `sim_mat`).
#' @return A list containing the posterior `Mean`, `Median`, `Lower_CI` (2.5%), `Upper_CI` (97.5%) on the calendar `DOY` scale, `Posterior_Draws`, and the biological minimum day `D_min`.
#' @examples
#' data(sim_carabids)
#' mod <- mgcv::gam(
#'   Count ~ s(DOY, bs = "cc", k = 10) + offset(LogEffort),
#'   family = poisson(), data = sim_carabids,
#'   knots = list(DOY = c(0.5, 365.5))
#' )
#' nd <- create_newdata(mod, doy = "DOY")
#' sim <- simulate_posterior_density(mod, nd, n_sims = 100, warnings = FALSE)
#' estimate_peak(sim)$Mean
#' @export
estimate_peak <- function(sim_mat, ref_sim_mat = NULL) {
  grid <- get_doy_grid(sim_mat)
  dt <- grid$dt

  base_dens <- if (!is.null(ref_sim_mat)) rowMeans(ref_sim_mat) else rowMeans(sim_mat)
  origin <- compute_doby_origin(base_dens, grid$doy)

  shifted_mat <- sim_mat[origin$shift_order, , drop = FALSE]
  doby_peaks <- apply(shifted_mat, 2, which.max)

  mean_doby <- mean(doby_peaks)
  med_doby <- stats::median(doby_peaks)
  low_doby <- stats::quantile(doby_peaks, 0.025)
  high_doby <- stats::quantile(doby_peaks, 0.975)

  return(list(
    Mean = wrap_doby_to_doy(mean_doby, origin$D_min, dt),
    Median = wrap_doby_to_doy(med_doby, origin$D_min, dt),
    Lower_CI = wrap_doby_to_doy(low_doby, origin$D_min, dt),
    Upper_CI = wrap_doby_to_doy(high_doby, origin$D_min, dt),
    Posterior_Draws = wrap_doby_to_doy(doby_peaks, origin$D_min, dt),
    D_min = origin$D_min
  ))
}
